package net.civeira.phylax.feature.access.dcrinitialaccesstoken.domain;

import java.time.LocalDateTime;
import java.time.ZoneId;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.identity.tenant.domain.TenantReference;

class DcrInitialAccessTokenChangeSetUnitTest {

  /**
   * @autogenerated CachedGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_dcr_initial_access_token_change_set_builder() {
    DcrInitialAccessTokenChangeSet one = new DcrInitialAccessTokenChangeSet().uid("one")
        .tenant(TenantReference.of("one")).description("one").tokenHashPlain("one")
        .expiresAt(LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid"))
            .toOffsetDateTime())
        .maxUses(1).uses(1).allowedGrantTypes("one").revokedAt(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime())
        .version(1).newUid();
    one.uid("two");
    Assertions.assertEquals("two", one.getUid().get(), "Value must equals to the assigned value");
    one.unset("uid");
    Assertions.assertFalse(one.getUid().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(TenantReference.of("one"), one.getTenant().get(),
        "Value must equals to the intial value");
    one.tenant(TenantReference.of("two"));
    Assertions.assertEquals(TenantReference.of("two"), one.getTenant().get(),
        "Value must equals to the assigned value");
    one.unset("tenant");
    Assertions.assertFalse(one.getTenant().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getDescription().get(),
        "Value must equals to the intial value");
    one.description("two");
    Assertions.assertEquals("two", one.getDescription().get(),
        "Value must equals to the assigned value");
    one.unset("description");
    Assertions.assertFalse(one.getDescription().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getExpiresAt().get(), "Value must equals to the intial value");
    one.expiresAt(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Assertions.assertEquals(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getExpiresAt().get(), "Value must equals to the assigned value");
    one.unset("expiresAt");
    Assertions.assertFalse(one.getExpiresAt().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(1, one.getMaxUses().get(), "Value must equals to the intial value");
    one.maxUses(2);
    Assertions.assertEquals(2, one.getMaxUses().get(), "Value must equals to the assigned value");
    one.unset("maxUses");
    Assertions.assertFalse(one.getMaxUses().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(1, one.getUses().get(), "Value must equals to the intial value");
    one.uses(2);
    Assertions.assertEquals(2, one.getUses().get(), "Value must equals to the assigned value");
    one.unset("uses");
    Assertions.assertFalse(one.getUses().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getAllowedGrantTypes().get(),
        "Value must equals to the intial value");
    one.allowedGrantTypes("two");
    Assertions.assertEquals("two", one.getAllowedGrantTypes().get(),
        "Value must equals to the assigned value");
    one.unset("allowedGrantTypes");
    Assertions.assertFalse(one.getAllowedGrantTypes().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getRevokedAt().get(), "Value must equals to the intial value");
    one.revokedAt(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Assertions.assertEquals(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getRevokedAt().get(), "Value must equals to the assigned value");
    one.unset("revokedAt");
    Assertions.assertFalse(one.getRevokedAt().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(0, one.getVersion().get(), "Value must equals to the intial value");
    one.version(2);
    Assertions.assertEquals(2, one.getVersion().get(), "Value must equals to the assigned value");
    one.unset("version");
    Assertions.assertFalse(one.getVersion().isPresent(),
        "After unset, the valeue must be dissapear");
  }
}
